// lib/domain/primitives.ts
import { z } from "zod";

/** Every table's primary key is a UUID generated by Postgres. */
export const idSchema = z.string().uuid();

/** ISO-8601 timestamp as returned by Postgres (timestamptz). */
export const timestampSchema = z.string();

/** Calendar date as YYYY-MM-DD, or a partial date when the exact day is unknown. */
export const dateSchema = z.string().regex(/^\d{4}(-\d{2}(-\d{2})?)?$/);

/** How much of a watch date the user actually knows. */
export const datePrecisionSchema = z.enum(["day", "month", "year", "unknown"]);

/** Ratings run 1–10 in half steps; null means unrated. */
export const ratingSchema = z
  .number()
  .min(1)
  .max(10)
  .refine((n) => Number.isInteger(n * 2), "Ratings use half steps");
